class Solution:
    def divisibilityArray(self, word: str, m: int) -> List[int]:
        res, rem = [], 0
        for ch in word:
            rem = (rem * 10 + int(ch)) % m
            res.append(1 if rem == 0 else 0)
        return res

c.cpp:
class Solution {
public:
    vector<int> divisibilityArray(string word, int m) {
        vector<int> res;
        long long rem = 0;
        for (char ch : word) {
            rem = (rem * 10 + (ch - '0')) % m;
            res.push_back(rem == 0 ? 1 : 0);
        }
        return res;
    }
};

c.java:
class Solution {
    public int[] divisibilityArray(String word, int m) {
        int n = word.length();
        int[] res = new int[n];
        long rem = 0;
        for (int i = 0; i < n; ++i) {
            rem = (rem * 10 + (word.charAt(i) - '0')) % m;
            res[i] = rem == 0 ? 1 : 0;
        }
        return res;
    }
}

